<?php page_start('Bookings — MWCN ERP'); ?><section class="section"><div class="wrap"><p class="kicker">MWCN ERP</p><h1 class="display mt-3 text-5xl">Bookings & payments</h1>@if(session('success'))<p class="mt-5 text-green-300">{{ session('success') }}</p>@endif<div class="mt-8 overflow-x-auto"><table class="w-full text-left text-sm"><thead><tr class="border-b border-line"><th class="p-3">Reference</th><th>When</th><th>Customer</th><th>Total</th><th>Status</th><th>Payment</th><th>Action</th></tr></thead><tbody>@foreach($bookings as $booking)<tr class="border-b border-line"><td class="p-3">{{ $booking->reference }}</td><td>{{ $booking->starts_at->setTimezone($booking->resource->timezone)->format('M j, Y g:i A') }}</td><td>{{ $booking->customer_name }}<br><span class="text-dim">{{ $booking->customer_email }}</span></td><td>${{ number_format($booking->total_cents/100,2) }}</td><td>{{ ucfirst(str_replace('_',' ',$booking->status)) }}</td><td>{{ ucfirst(str_replace('_',' ',$booking->payment_status)) }}</td><td><form method="post" action="{{ route('admin.bookings.payment',$booking) }}" class="grid gap-2">@csrf @method('PATCH')<select class="input" name="payment_status">@foreach(['paid','pending','failed','cancelled','expired','refunded'] as $status)<option @selected($booking->payment_status===$status)>{{ $status }}</option>@endforeach</select><input class="input" name="reason" placeholder="Reason" required><button class="btn btn-ghost">Update</button></form></td></tr>@endforeach</tbody></table></div>{{ $bookings->links() }}</div></section><?php page_end(); ?>
